import{_ as t,c as a,o as i,aj as r}from"./chunks/framework.CDhdelVI.js";const m=JSON.parse('{"title":"Cold Fermentation","description":"Cold fermentation tips for developing flavor, structure, and extensibility in dough with extended refrigerator resting.","frontmatter":{"title":"Cold Fermentation","description":"Cold fermentation tips for developing flavor, structure, and extensibility in dough with extended refrigerator resting.","head":[["meta",{"name":"description","content":"Cold fermentation tips for developing flavor, structure, and extensibility in dough with extended refrigerator resting."}],["meta",{"property":"og:title","content":"Cold Fermentation"}],["meta",{"property":"og:description","content":"Cold fermentation tips for developing flavor, structure, and extensibility in dough with extended refrigerator resting."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/cold-fermentation.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Cold Fermentation"}],["meta",{"name":"twitter:description","content":"Cold fermentation tips for developing flavor, structure, and extensibility in dough with extended refrigerator resting."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/cold-fermentation.html"}]]},"headers":[],"relativePath":"guides/cold-fermentation.md","filePath":"guides/cold-fermentation.md"}'),n={name:"guides/cold-fermentation.md"};function o(l,e,d,s,h,c){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="cold-fermentation" tabindex="-1">Cold Fermentation <a class="header-anchor" href="#cold-fermentation" aria-label="Permalink to “Cold Fermentation”">​</a></h1><p>Cold fermentation is the long game: slower yeast, better flavor, and dough that is usually easier to handle. You are trading clock time for better structure and taste.</p><h2 id="core-range" tabindex="-1">Core Range <a class="header-anchor" href="#core-range" aria-label="Permalink to “Core Range”">​</a></h2><ul><li>Refrigerate dough <strong>12-48 hours</strong></li><li>Use a covered container to prevent drying</li><li>Plan for dough to proof more slowly after shaping</li></ul><h2 id="why-it-works" tabindex="-1">Why It Works <a class="header-anchor" href="#why-it-works" aria-label="Permalink to “Why It Works”">​</a></h2><ul><li>Slower fermentation builds deeper flavor</li><li>Time improves gluten organization and extensibility</li><li>Cooler dough is often easier to divide and shape cleanly</li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to “Practical Notes”">​</a></h2><ul><li>If dough seems sluggish out of the fridge, give it extra bench time before baking.</li><li>If dough overproofs in cold storage, reduce yeast slightly next batch.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/ingredients/yeast.html">Yeast</a></li><li><a href="/guides/folding.html">Folding</a></li><li><a href="/guides/no-knead-vs-kneading.html">No-Knead vs Kneading</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul>',12)])])}const f=t(n,[["render",o]]);export{m as __pageData,f as default};
